/**
 * Pure helpers shared by every engine. No n8n globals, no I/O.
 */

const HTML_ENTITIES = {
  amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', ndash: '-', mdash: '-',
  lsquo: "'", rsquo: "'", ldquo: '"', rdquo: '"', hellip: '...', laquo: '"', raquo: '"',
