    `🔴 ${b('BEARISH SCENARIO')}`, scenarioBlock(fc.scenarios.bearish),
    RULE,
    `⚪ ${b('BASE / MIXED')}`, scenarioBlock(fc.scenarios.base),
    RULE,
    `🎯 ${b('WHAT MATTERS MOST')}`, numbered(fc.what_matters_most, 4),
