    `${b('POLITICS:')} ${esc(catSummary.POLITICS || 'no high-relevance events (24h)')}`,
    `${b('MACRO STATE:')} ${L.macro ? esc(L.macro.primary) : 'n/a'} — ${esc(catSummary.MACRO || 'no high-relevance events (24h)')}`,
